    return { ok: false };
  }

  const normalized = rawValue.replace(/_/g, "");
  const sign = normalized.startsWith("-") ? -1n : 1n;
  const digits = normalized.startsWith("+") || normalized.startsWith("-")
    ? normalized.slice(1)
    : normalized;

  return {
    ok: true,
    value: sign * BigInt(digits),
  };
}

