  return `usage: ${programName} [-h] --a A --b B`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}`;
}

function parseOptionToken(token) {
  if (token === "--a" || token === "--b") {
    return { name: token.slice(2), inlineValue: undefined };
  }

  if (token.startsWith("--a=") || token.startsWith("--b=")) {
    const equalsIndex = token.indexOf("=");
    return {
      name: token.slice(2, equalsIndex),
      inlineValue: token.slice(equalsIndex + 1),
    };
  }

  return null;
}

function looksLikeMissingValue(token) {
  if (token === undefined) {
    return true;
  }

  if (token === "-h" || token === "--help" || token.startsWith("--")) {
    return true;
  }

  return token.startsWith("-") && !parsePythonIntLiteral(token).ok;
}

function parseIntArgument(programName, optionToken, rawValue) {
  const parsed = parsePythonIntLiteral(rawValue);

  if (!parsed.ok) {
    return {
      ok: false,
      errorText: formatError(programName, `argument ${optionToken}: invalid int value: '${rawValue}'`),
    };
  }

  return { ok: true, value: parsed.value };
}

export function parseCommandLine(argv, programName) {
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h" || token === "--help") {
      return {
        kind: "help",
