export class PythonValueError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValueError";
  }
}

export function buildBytePair(values) {
  return values.map((value) => {
    if (value < 0n || value > 255n) {
      throw new PythonValueError("bytes must be in range(0, 256)");
    }

    return Number(value);
  });
}

export function parseTwoUint8Struct(bytePair) {
  return {
    field1: bytePair[0],
    field2: bytePair[1],
  };
}

export function formatContainer(result) {
  return `Container: \n    field1 = ${result.field1}\n    field2 = ${result.field2}`;
}

