import { parseCommandLine } from "./lib/cli.mjs";
import {
  PythonValueError,
  buildBytePair,
  formatContainer,
  parseTwoUint8Struct,
} from "./lib/construct_like.mjs";

function getProgramName(scriptPath) {
  const normalized = scriptPath.replace(/\\/g, "/");
  const parts = normalized.split("/");
  return parts[parts.length - 1] || scriptPath;
}

export function main(argv = process.argv.slice(2)) {
  const programName = getProgramName(process.argv[1] || "test4.mjs");
  const parsed = parseCommandLine(argv, programName);

  if (parsed.kind === "help") {
    process.stdout.write(`${parsed.text}\n`);
    return 0;
  }

  if (parsed.kind === "error") {
    process.stderr.write(`${parsed.text}\n`);
    return parsed.exitCode;
  }

  const bytePair = buildBytePair([parsed.values.a, parsed.values.b]);
  const result = parseTwoUint8Struct(bytePair);
  process.stdout.write(`${formatContainer(result)}\n`);
  return 0;
}

try {
  process.exitCode = main();
} catch (error) {
  if (error instanceof PythonValueError) {
    process.stderr.write(`${error.name}: ${error.message}\n`);
    process.exitCode = 1;
  } else {
    throw error;
  }
}
